-- =====================================================================
--  ONLINE SHOP DATABASE  (MySQL / MariaDB - XAMPP compatible)
--  Database : online_shop
--  Engine   : InnoDB, charset utf8mb4
--  Import   : phpMyAdmin > Import > choose this file > Go
--             (or: mysql -u root < online_shop.sql)
--  NOTE     : the script DROPs and re-creates the database `online_shop`.
-- =====================================================================

DROP DATABASE IF EXISTS online_shop;
CREATE DATABASE online_shop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE online_shop;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET time_zone = '+00:00';

-- ---------------------------------------------------------------------
-- 1) CATALOG
-- ---------------------------------------------------------------------
CREATE TABLE categories (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  parent_id   INT UNSIGNED NULL,
  name        VARCHAR(100) NOT NULL,
  slug        VARCHAR(120) NOT NULL,
  description VARCHAR(255) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_categories_slug (slug),
  KEY idx_categories_parent (parent_id),
  CONSTRAINT fk_categories_parent FOREIGN KEY (parent_id) REFERENCES categories (id) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Product categories (self-referencing tree: category -> sub-category)';

CREATE TABLE brands (
  id      INT UNSIGNED NOT NULL AUTO_INCREMENT,
  name    VARCHAR(100) NOT NULL,
  country VARCHAR(60)  NULL,
  website VARCHAR(150) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_brands_name (name)
) ENGINE=InnoDB COMMENT='Product brands / publishers';

CREATE TABLE suppliers (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  company_name VARCHAR(120) NOT NULL,
  contact_name VARCHAR(100) NULL,
  email        VARCHAR(150) NOT NULL,
  phone        VARCHAR(30)  NULL,
  country      VARCHAR(60)  NULL,
  city         VARCHAR(80)  NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_suppliers_email (email)
) ENGINE=InnoDB COMMENT='Wholesale suppliers';

CREATE TABLE products (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
  category_id    INT UNSIGNED NOT NULL,
  brand_id       INT UNSIGNED NOT NULL,
  supplier_id    INT UNSIGNED NOT NULL,
  sku            VARCHAR(30)  NOT NULL,
  name           VARCHAR(200) NOT NULL,
  description    TEXT         NULL,
  price          DECIMAL(10,2) NOT NULL,
  cost_price     DECIMAL(10,2) NOT NULL,
  stock_quantity INT UNSIGNED NOT NULL DEFAULT 0,
  reorder_level  INT UNSIGNED NOT NULL DEFAULT 10,
  weight_kg      DECIMAL(6,2) NULL,
  is_active      TINYINT(1)   NOT NULL DEFAULT 1,
  created_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_products_sku (sku),
  KEY idx_products_category (category_id),
  KEY idx_products_brand (brand_id),
  KEY idx_products_supplier (supplier_id),
  KEY idx_products_price (price),
  FULLTEXT KEY ft_products_name_desc (name, description),
  CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_products_brand    FOREIGN KEY (brand_id)    REFERENCES brands (id)     ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_products_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers (id)  ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_products_price CHECK (price >= 0),
  CONSTRAINT chk_products_cost  CHECK (cost_price >= 0)
) ENGINE=InnoDB COMMENT='Products for sale';

CREATE TABLE product_images (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  product_id INT UNSIGNED NOT NULL,
  image_url  VARCHAR(255) NOT NULL,
  alt_text   VARCHAR(255) NULL,
  is_primary TINYINT(1)   NOT NULL DEFAULT 0,
  sort_order TINYINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  KEY idx_product_images_product (product_id),
  CONSTRAINT fk_product_images_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Product photos (1 product -> many images)';

-- ---------------------------------------------------------------------
-- 2) CUSTOMERS
-- ---------------------------------------------------------------------
CREATE TABLE customers (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  first_name    VARCHAR(60)  NOT NULL,
  last_name     VARCHAR(60)  NOT NULL,
  email         VARCHAR(150) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  phone         VARCHAR(30)  NULL,
  gender        ENUM('male','female','other') NULL,
  birth_date    DATE         NULL,
  is_active     TINYINT(1)   NOT NULL DEFAULT 1,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_login_at DATETIME     NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_customers_email (email),
  KEY idx_customers_last_name (last_name)
) ENGINE=InnoDB COMMENT='Registered customers';

CREATE TABLE addresses (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
  customer_id    INT UNSIGNED NOT NULL,
  recipient_name VARCHAR(120) NOT NULL,
  address_line1  VARCHAR(150) NOT NULL,
  address_line2  VARCHAR(150) NULL,
  city           VARCHAR(80)  NOT NULL,
  state          VARCHAR(80)  NULL,
  postal_code    VARCHAR(15)  NOT NULL,
  country        VARCHAR(60)  NOT NULL,
  is_default     TINYINT(1)   NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_addresses_customer (customer_id),
  KEY idx_addresses_city (city),
  CONSTRAINT fk_addresses_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Customer addresses (1 customer -> many addresses)';

-- ---------------------------------------------------------------------
-- 3) SALES
-- ---------------------------------------------------------------------
CREATE TABLE coupons (
  id               INT UNSIGNED NOT NULL AUTO_INCREMENT,
  code             VARCHAR(30)  NOT NULL,
  description      VARCHAR(150) NULL,
  discount_type    ENUM('percent','fixed') NOT NULL,
  discount_value   DECIMAL(8,2) NOT NULL,
  min_order_amount DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  max_uses         INT UNSIGNED NULL,
  used_count       INT UNSIGNED NOT NULL DEFAULT 0,
  valid_from       DATE NOT NULL,
  valid_to         DATE NOT NULL,
  is_active        TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  UNIQUE KEY uq_coupons_code (code),
  CONSTRAINT chk_coupons_value CHECK (discount_value > 0)
) ENGINE=InnoDB COMMENT='Discount coupons';

CREATE TABLE orders (
  id                  INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_number        VARCHAR(20)  NOT NULL,
  customer_id         INT UNSIGNED NOT NULL,
  shipping_address_id INT UNSIGNED NOT NULL,
  billing_address_id  INT UNSIGNED NOT NULL,
  coupon_id           INT UNSIGNED NULL,
  status              ENUM('pending','processing','shipped','delivered','cancelled','returned') NOT NULL DEFAULT 'pending',
  order_date          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  subtotal            DECIMAL(10,2) NOT NULL,
  discount_amount     DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  shipping_fee        DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  tax_amount          DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  total_amount        DECIMAL(10,2) NOT NULL,
  notes               VARCHAR(255) NULL,
  updated_at          DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_orders_number (order_number),
  KEY idx_orders_customer (customer_id),
  KEY idx_orders_date (order_date),
  KEY idx_orders_status (status),
  KEY idx_orders_shipping_addr (shipping_address_id),
  KEY idx_orders_billing_addr (billing_address_id),
  KEY idx_orders_coupon (coupon_id),
  CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id)         REFERENCES customers (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_orders_ship_adr FOREIGN KEY (shipping_address_id) REFERENCES addresses (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_orders_bill_adr FOREIGN KEY (billing_address_id)  REFERENCES addresses (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT fk_orders_coupon   FOREIGN KEY (coupon_id)           REFERENCES coupons (id)   ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT chk_orders_total CHECK (total_amount >= 0)
) ENGINE=InnoDB COMMENT='Customer orders (header)';

CREATE TABLE order_items (
  id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_id        INT UNSIGNED NOT NULL,
  product_id      INT UNSIGNED NOT NULL,
  quantity        SMALLINT UNSIGNED NOT NULL,
  unit_price      DECIMAL(10,2) NOT NULL,
  discount_amount DECIMAL(10,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (id),
  UNIQUE KEY uq_order_items_order_product (order_id, product_id),
  KEY idx_order_items_product (product_id),
  CONSTRAINT fk_order_items_order   FOREIGN KEY (order_id)   REFERENCES orders (id)   ON DELETE CASCADE  ON UPDATE CASCADE,
  CONSTRAINT fk_order_items_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT chk_order_items_qty CHECK (quantity > 0)
) ENGINE=InnoDB COMMENT='Order lines (orders <-> products, many-to-many); unit_price = price at purchase time';

CREATE TABLE payments (
  id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_id        INT UNSIGNED NOT NULL,
  method          ENUM('credit_card','paypal','bank_transfer','cash_on_delivery','wallet') NOT NULL,
  status          ENUM('pending','completed','failed','refunded') NOT NULL DEFAULT 'pending',
  amount          DECIMAL(10,2) NOT NULL,
  transaction_ref VARCHAR(30) NULL,
  created_at      DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  paid_at         DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_payments_txn (transaction_ref),
  KEY idx_payments_order (order_id),
  KEY idx_payments_status (status),
  CONSTRAINT fk_payments_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Payment attempts (1 order -> 1..n payments)';

CREATE TABLE shipments (
  id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
  order_id        INT UNSIGNED NOT NULL,
  carrier         VARCHAR(60) NOT NULL,
  tracking_number VARCHAR(30) NOT NULL,
  status          ENUM('in_transit','delivered','returned') NOT NULL DEFAULT 'in_transit',
  shipped_at      DATETIME NULL,
  delivered_at    DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_shipments_tracking (tracking_number),
  KEY idx_shipments_order (order_id),
  CONSTRAINT fk_shipments_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Shipments of orders';

-- ---------------------------------------------------------------------
-- 4) CUSTOMER ACTIVITY
-- ---------------------------------------------------------------------
CREATE TABLE reviews (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  product_id    INT UNSIGNED NOT NULL,
  customer_id   INT UNSIGNED NOT NULL,
  rating        TINYINT UNSIGNED NOT NULL,
  title         VARCHAR(120) NULL,
  comment       TEXT NULL,
  helpful_votes INT UNSIGNED NOT NULL DEFAULT 0,
  is_approved   TINYINT(1) NOT NULL DEFAULT 1,
  created_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_reviews_product_customer (product_id, customer_id),
  KEY idx_reviews_customer (customer_id),
  CONSTRAINT fk_reviews_product  FOREIGN KEY (product_id)  REFERENCES products (id)  ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_reviews_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT chk_reviews_rating CHECK (rating BETWEEN 1 AND 5)
) ENGINE=InnoDB COMMENT='Product reviews (one review per customer per product)';

CREATE TABLE wishlists (
  customer_id INT UNSIGNED NOT NULL,
  product_id  INT UNSIGNED NOT NULL,
  added_at    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (customer_id, product_id),
  KEY idx_wishlists_product (product_id),
  CONSTRAINT fk_wishlists_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_wishlists_product  FOREIGN KEY (product_id)  REFERENCES products (id)  ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Wishlist (customers <-> products, many-to-many, composite PK)';

CREATE TABLE carts (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT,
  customer_id INT UNSIGNED NOT NULL,
  created_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_carts_customer (customer_id),
  CONSTRAINT fk_carts_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB COMMENT='Active shopping carts (1 customer -> 1 cart)';

CREATE TABLE cart_items (
  cart_id    INT UNSIGNED NOT NULL,
  product_id INT UNSIGNED NOT NULL,
  quantity   SMALLINT UNSIGNED NOT NULL DEFAULT 1,
  added_at   DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (cart_id, product_id),
  KEY idx_cart_items_product (product_id),
  CONSTRAINT fk_cart_items_cart    FOREIGN KEY (cart_id)    REFERENCES carts (id)    ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT fk_cart_items_product FOREIGN KEY (product_id) REFERENCES products (id) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT chk_cart_items_qty CHECK (quantity > 0)
) ENGINE=InnoDB COMMENT='Cart lines';


