-- ---------------------------------------------------------------------
-- 5) VIEWS
-- ---------------------------------------------------------------------
CREATE OR REPLACE VIEW v_order_summary AS
SELECT o.id AS order_id, o.order_number, o.order_date, o.status,
       CONCAT(c.first_name, ' ', c.last_name) AS customer_name, c.email,
       COUNT(oi.id) AS line_items, SUM(oi.quantity) AS total_units, o.total_amount
FROM orders o
JOIN customers c    ON c.id = o.customer_id
JOIN order_items oi ON oi.order_id = o.id
GROUP BY o.id, o.order_number, o.order_date, o.status, c.first_name, c.last_name, c.email, o.total_amount;

CREATE OR REPLACE VIEW v_product_sales AS
SELECT p.id AS product_id, p.sku, p.name AS product_name, cat.name AS category, b.name AS brand,
       COALESCE(SUM(CASE WHEN o.status NOT IN ('cancelled') THEN oi.quantity END), 0) AS units_sold,
       COALESCE(SUM(CASE WHEN o.status NOT IN ('cancelled') THEN oi.quantity * oi.unit_price - oi.discount_amount END), 0) AS revenue
FROM products p
JOIN categories cat ON cat.id = p.category_id
JOIN brands b       ON b.id = p.brand_id
LEFT JOIN order_items oi ON oi.product_id = p.id
LEFT JOIN orders o       ON o.id = oi.order_id
GROUP BY p.id, p.sku, p.name, cat.name, b.name;

SET FOREIGN_KEY_CHECKS = 1;
-- END OF SCRIPT
